const img = $input.first().json.image_generated[0]

const res = {html_fulldata: {
  language: img.language,
  subject : img.subject,
  html: img.body_html,
  imgs: img.image_prompts.map((item,index)=>{
    return{
      image_placeholder: item.image_placeholder,
      prompt: item.prompt,
      url: img.image_generated[index].url
    }
  })
}}

return res

const items = $input.all();
const updatedItems = items.map((item) => {
  const timestamp = Date.now();
  const randomNum = Math.floor(Math.random() * 1000);
  const newFileName = `${timestamp}${randomNum}.png`;
  item.json.fileName = newFileName;
  return item;
});
return updatedItems;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const res = []
for (const item of $input.all()) {
  res.push({
    url: `https://storage.googleapis.com/junction-changlu/` + item.json.name
  })
}

return res;

const items = $input.all();
let nonZeroFile = null;

const updatedItems = items.map((item) => {
  if (item?.binary?.fileSize === "0") {
    if (nonZeroFile) {
      item.binary = nonZeroFile;
    }
  } else {
    nonZeroFile = item.binary;
  }
  return item;
});

return updatedItems;
